import json
import os

async def handler(params):
    """Search the web. Tries Tavily first, then Brave Search API, then returns stub."""
    query = params.get("query", "")
    if not query:
        return "Error: query required"
    tavily_key = os.environ.get("TAVILY_API_KEY", "")
    if tavily_key:
        try:
            import httpx
            async with httpx.AsyncClient(timeout=15) as client:
                resp = await client.post(
                    "https://api.tavily.com/search",
                    json={"query": query, "max_results": 5, "api_key": tavily_key},
                )
                resp.raise_for_status()
                data = resp.json()
                results = []
                for r in data.get("results", [])[:5]:
                    results.append({
                        "title": r.get("title", ""),
                        "url": r.get("url", ""),
                        "content": r.get("content", "")[:200],
                    })
                return json.dumps(results)
        except Exception as e:
            return f"Error searching: {e}"
    brave_key = os.environ.get("BRAVE_API_KEY", "")
    if brave_key:
        try:
            import httpx
            async with httpx.AsyncClient(timeout=15) as client:
                resp = await client.get(
                    "https://api.search.brave.com/res/v1/web/search",
                    params={"q": query, "count": 5},
                    headers={"X-Subscription-Token": brave_key, "Accept": "application/json"},
                )
                resp.raise_for_status()
                data = resp.json()
                results = []
                for r in data.get("web", {}).get("results", [])[:5]:
                    results.append({
                        "title": r.get("title", ""),
                        "url": r.get("url", ""),
                        "description": r.get("description", ""),
                    })
                return json.dumps(results)
        except Exception as e:
            return f"Error searching: {e}"
    return json.dumps({
        "status": "no_api_key",
        "message": f"Web search for '{query}' requires TAVILY_API_KEY or BRAVE_API_KEY in environment.",
    })
